class Scope {
  constructor(parent = null) { this.bindings = new Map(); this.parent = parent; }
  define(name, symbol) {
    if (this.bindings.has(name)) return false;
    this.bindings.set(name, symbol); return true;
  }
  lookup(name) {                                        // innermost outward
    for (let s = this; s !== null; s = s.parent) {
      const sym = s.bindings.get(name); if (sym !== undefined) return sym;
    }
    return undefined;
  }
}
